//! Special functions (ADR-0004). Every routine is verified against scipy test vectors
//! generated by oracle/numerics_ref.py.
//!
//! Published constants (Lanczos, AS241) are kept with every printed digit so they can be
//! checked against the source digit by digit; the extra digits round to the same f64.
#![allow(clippy::excessive_precision)]

use std::f64::consts::PI;

#[derive(Clone, Copy, Debug, PartialEq, Eq)]
pub enum NumError {
    Domain,
    NoConvergence,
}

const LANCZOS_G: f64 = 7.0;
const LANCZOS: [f64; 9] = [
    0.999_999_999_999_809_9,
    676.520_368_121_885_1,
    -1_259.139_216_722_402_8,
    771.323_428_777_653_1,
    -176.615_029_162_140_6,
    12.507_343_278_686_905,
    -0.138_571_095_265_720_12,
    9.984_369_578_019_572e-6,
    1.505_632_735_149_311_6e-7,
];

/// ln Γ(x) for x > 0 (Lanczos, g = 7, n = 9).
pub fn ln_gamma(x: f64) -> Result<f64, NumError> {
    if x.is_nan() || x <= 0.0 || x.is_infinite() {
        return Err(NumError::Domain);
    }
    if x < 0.5 {
        // Reflection keeps the series in its accurate range.
        return Ok((PI / (PI * x).sin()).ln() - ln_gamma(1.0 - x)?);
    }
    let x = x - 1.0;
    let mut a = LANCZOS[0];
    let t = x + LANCZOS_G + 0.5;
    for (i, c) in LANCZOS.iter().enumerate().skip(1) {
        a += c / (x + i as f64);
    }
    Ok(0.5 * (2.0 * PI).ln() + (x + 0.5) * t.ln() - t + a.ln())
}

/// Continued fraction for I_x(a,b) (modified Lentz). `y` is 1 - x supplied exactly by the caller.
fn beta_cf(a: f64, b: f64, x: f64) -> Result<f64, NumError> {
    const MAX_IT: usize = 500;
    const EPS: f64 = 1e-16;
    const TINY: f64 = 1e-300;
    let (qab, qap, qam) = (a + b, a + 1.0, a - 1.0);
    let mut c = 1.0;
    let mut d = 1.0 - qab * x / qap;
    if d.abs() < TINY {
        d = TINY;
    }
    d = 1.0 / d;
    let mut h = d;
    for m in 1..=MAX_IT {
        let m = m as f64;
        let m2 = 2.0 * m;
        let aa = m * (b - m) * x / ((qam + m2) * (a + m2));
        d = 1.0 + aa * d;
        if d.abs() < TINY {
            d = TINY;
        }
        c = 1.0 + aa / c;
        if c.abs() < TINY {
            c = TINY;
        }
        d = 1.0 / d;
        h *= d * c;
        let aa = -(a + m) * (qab + m) * x / ((a + m2) * (qap + m2));
        d = 1.0 + aa * d;
        if d.abs() < TINY {
            d = TINY;
        }
        c = 1.0 + aa / c;
        if c.abs() < TINY {
            c = TINY;
        }
        d = 1.0 / d;
        let del = d * c;
        h *= del;
        if (del - 1.0).abs() < EPS {
            return Ok(h);
        }
    }
    Err(NumError::NoConvergence)
}

/// Regularised incomplete beta I_x(a,b) with y = 1 - x passed exactly (avoids cancellation).
pub fn beta_inc(a: f64, b: f64, x: f64, y: f64) -> Result<f64, NumError> {
    if a.is_nan() || b.is_nan() || a <= 0.0 || b <= 0.0 || !(0.0..=1.0).contains(&x) || !(0.0..=1.0).contains(&y) || (x + y - 1.0).abs() > 1e-12 {
        return Err(NumError::Domain);
    }
    if x == 0.0 {
        return Ok(0.0);
    }
    if y == 0.0 {
        return Ok(1.0);
    }
    let ln_front = ln_gamma(a + b)? - ln_gamma(a)? - ln_gamma(b)? + a * x.ln() + b * y.ln();
    let front = ln_front.exp();
    if x < (a + 1.0) / (a + b + 2.0) {
        Ok(front * beta_cf(a, b, x)? / a)
    } else {
        Ok(1.0 - front * beta_cf(b, a, y)? / b)
    }
}

fn poly(c: &[f64], r: f64) -> f64 {
    c.iter().rev().fold(0.0, |acc, &k| acc * r + k)
}

/// Φ⁻¹(p), Wichura AS241 (PPND16). Returns ±∞ at p = 0 or 1.
pub fn ndtri(p: f64) -> Result<f64, NumError> {
    if !(0.0..=1.0).contains(&p) {
        return Err(NumError::Domain);
    }
    if p == 0.0 {
        return Ok(f64::NEG_INFINITY);
    }
    if p == 1.0 {
        return Ok(f64::INFINITY);
    }
    const A: [f64; 8] = [
        3.387_132_872_796_366_608,
        133.141_667_891_784_377_45,
        1_971.590_950_306_551_442_7,
        13_731.693_765_509_461_125,
        45_921.953_931_549_871_457,
        67_265.770_927_008_700_853,
        33_430.575_583_588_128_105,
        2_509.080_928_730_122_672_7,
    ];
    const B: [f64; 8] = [
        1.0,
        42.313_330_701_600_911_252,
        687.187_007_492_057_908_3,
        5_394.196_021_424_751_107_7,
        21_213.794_301_586_595_867,
        39_307.895_800_092_710_61,
        28_729.085_735_721_942_674,
        5_226.495_278_852_854_561,
    ];
    const C: [f64; 8] = [
        1.423_437_110_749_683_577_34,
        4.630_337_846_156_545_295_9,
        5.769_497_221_460_691_405_5,
        3.647_848_324_763_204_605_04,
        1.270_458_252_452_368_382_58,
        0.241_780_725_177_450_611_77,
        0.022_723_844_989_269_184_583_3,
        7.745_450_142_783_414_076_4e-4,
    ];
    const D: [f64; 8] = [
        1.0,
        2.053_191_626_637_758_821_87,
        1.676_384_830_183_803_849_4,
        0.689_767_334_985_100_004_55,
        0.148_103_976_427_480_074_59,
        0.015_198_666_563_616_457_196_6,
        5.475_938_084_995_344_946e-4,
        1.050_750_071_644_416_843_24e-9,
    ];
    const E: [f64; 8] = [
        6.657_904_643_501_103_777_2,
        5.463_784_911_164_114_369_9,
        1.784_826_539_917_291_335_8,
        0.296_560_571_828_504_891_23,
        0.026_532_189_526_576_123_093,
        0.001_242_660_947_388_078_438_6,
        2.711_555_568_743_487_578_15e-5,
        2.010_334_399_292_288_132_65e-7,
    ];
    const F: [f64; 8] = [
        1.0,
        0.599_832_206_555_887_937_69,
        0.136_929_880_922_735_805_31,
        0.014_875_361_290_850_614_852_5,
        7.868_691_311_456_132_591e-4,
        1.846_318_317_510_054_681_8e-5,
        1.421_511_758_316_445_888_7e-7,
        2.044_263_103_389_939_785_64e-15,
    ];
    let q = p - 0.5;
    if q.abs() <= 0.425 {
        let r = 0.180_625 - q * q;
        return Ok(q * poly(&A, r) / poly(&B, r));
    }
    let r = if q < 0.0 { p } else { 1.0 - p };
    let r = (-r.ln()).sqrt();
    let v = if r <= 5.0 {
        let r = r - 1.6;
        poly(&C, r) / poly(&D, r)
    } else {
        let r = r - 5.0;
        poly(&E, r) / poly(&F, r)
    };
    Ok(if q < 0.0 { -v } else { v })
}

/// Map a Student-t value to the normal quantile with the same tail probability,
/// computing the smaller tail directly so precision survives far into the tails.
pub fn t_to_z(t: f64, nu: f64) -> Result<f64, NumError> {
    if nu.is_nan() || nu <= 0.0 || t.is_nan() {
        return Err(NumError::Domain);
    }
    if t == 0.0 {
        return Ok(0.0);
    }
    if t.is_infinite() {
        return Ok(t.signum() * f64::INFINITY);
    }
    let t2 = t * t;
    let (x, y) = (nu / (nu + t2), t2 / (nu + t2));
    let tail = 0.5 * beta_inc(nu / 2.0, 0.5, x, y)?;
    let z = -ndtri(tail)?;
    Ok(if t > 0.0 { z } else { -z })
}

#[cfg(test)]
mod tests {
    use super::*;

    const VECTORS: &str = include_str!("../../oracle/vectors/numerics_vectors.txt");

    /// Relative tolerance, with an absolute floor only where the reference value can be ~0.
    fn close(got: f64, want: f64, rel: f64, abs: f64) -> bool {
        if want.is_infinite() {
            return got == want;
        }
        let err = (got - want).abs();
        err <= rel * want.abs() || err <= abs
    }

    #[test]
    fn agrees_with_scipy() {
        let mut n = 0;
        let mut worst = 0.0f64;
        for line in VECTORS.lines().filter(|l| !l.is_empty() && !l.starts_with('#')) {
            let f: Vec<&str> = line.split('\t').collect();
            let num = |i: usize| f[i].parse::<f64>().unwrap();
            let (got, want, rel, abs) = match f[0] {
                "lgamma" => (ln_gamma(num(1)).unwrap(), num(2), 1e-13, 1e-13),
                "betainc" => (beta_inc(num(1), num(2), num(3), num(4)).unwrap(), num(5), 1e-12, 0.0),
                "ndtri" => (ndtri(num(1)).unwrap(), num(2), 1e-14, 1e-15),
                "t2z" => (t_to_z(num(1), num(2)).unwrap(), num(3), 1e-11, 1e-13),
                other => panic!("unknown tag {other}"),
            };
            if want != 0.0 && want.is_finite() {
                worst = worst.max((got - want).abs() / want.abs());
            }
            assert!(close(got, want, rel, abs), "{line}: got {got:e}");
            n += 1;
        }
        assert!(n > 500, "too few vectors: {n}");
        eprintln!("numerics vectors: {n}, worst relative error {worst:e}");
    }

    #[test]
    fn domain_errors_are_reported_not_hidden() {
        assert_eq!(ln_gamma(0.0), Err(NumError::Domain));
        assert_eq!(beta_inc(1.0, 1.0, 0.3, 0.6), Err(NumError::Domain));
        assert_eq!(ndtri(1.5), Err(NumError::Domain));
        assert_eq!(t_to_z(1.0, 0.0), Err(NumError::Domain));
    }
}
